{"sql": "-- Check if wholesale dates match transaction dates
SELECT COUNT(*) as matching_dates 
FROM (
  SELECT DISTINCT substr(whsle_date, 1, 10) as wh_date FROM veg_whsle_df
) w
JOIN (
  SELECT DISTINCT substr(txn_date, 1, 10) as tx_date FROM veg_txn_df
) t ON w.wh_date = t.tx_date"}
